//@ProcessingGroup("aTM")
@Component("aTM-projector")
public class ATMProjector extends ATMEntityProjector {
		
	// core constructor
	public ATMProjector(ProjectorRegistry registry,
									ATMRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateATMEvent
     */
    @EventHandler( payloadType=CreateATMEvent.class )
    public void handle( CreateATMEvent event) {
	    LOGGER.info("handling CreateATMEvent - " + event );
	    ATM entity = new ATM();
            entity.setATMId( event.getATMId() );
            entity.setTerminalId( event.getTerminalId() );
            entity.setLocation( event.getLocation() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllATM( entity );
    }

    /*
     * @param	event UpdateATMEvent
     */
    @EventHandler( payloadType=UpdateATMEvent.class )
    public void handle( UpdateATMEvent event) {
    	LOGGER.info("handling UpdateATMEvent - " + event );
    	
	    ATM entity = new ATM();
            entity.setATMId( event.getATMId() );
            entity.setTerminalId( event.getTerminalId() );
            entity.setLocation( event.getLocation() );
            entity.setBranch( event.getBranch() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindATM( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllATM( entity );        
    }
    
    /*
     * @param	event DeleteATMEvent
     */
    @EventHandler( payloadType=DeleteATMEvent.class )
    public void handle( DeleteATMEvent event) {
    	LOGGER.info("handling DeleteATMEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	ATM entity = delete( event.getATMId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllATM( entity );

    }    

    /*
     * @param	event AssignBranchToATMEvent
     */
    @EventHandler( payloadType=AssignBranchToATMEvent.class)
    public void handle( AssignBranchToATMEvent event) {
	    LOGGER.info("handling AssignBranchToATMEvent - " + event );

	    // ------------------------------------------
	    // delegate to assignTo
	    // ------------------------------------------
	    ATM entity = assignBranch( event.getATMId(), event.getAssignment() );

	    // ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindATM( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllATM( entity );
    }
    

	/*
	 * @param	event UnAssignBranchFromATMEvent
	 */
	@EventHandler( payloadType=UnAssignBranchFromATMEvent.class)
	public void handle( UnAssignBranchFromATMEvent event) {
	    LOGGER.info("handling UnAssignBranchFromATMEvent - " + event );

	    // ------------------------------------------
	    // delegate to unAssignFrom
	    // ------------------------------------------
	    ATM entity = unAssignBranch( event.getATMId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindATM( entity );
	
		// ------------------------------------------
		// emit to subscribers that find all
		// ------------------------------------------    	
	    emitFindAllATM( entity );
	}




    /**
     * Method to retrieve the ATM via an ATMPrimaryKey.
     * @param 	id Long
     * @return 	ATM
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public ATM handle( FindATMQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getATMId() );
    }
    
    /**
     * Method to retrieve a collection of all ATMs
     *
     * @param	query	FindAllATMQuery 
     * @return 	List<ATM> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<ATM> handle( FindAllATMQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindATM,
 * but only if the id matches
 *
 * @param		entity	ATM
 */
	protected void emitFindATM( ATM entity ) {
		LOGGER.info("handling emitFindATM" );
		
	    queryUpdateEmitter.emit(FindATMQuery.class,
	                            query -> query.getFilter().getATMId().equals(entity.getATMId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllATM
	 * 
	 * @param		entity	ATM
	 */
	protected void emitFindAllATM( ATM entity ) {
		LOGGER.info("handling emitFindAllATM" );
		
	    queryUpdateEmitter.emit(FindAllATMQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(ATMProjector.class.getName());

}
